"""Residentado Médico · lote 7, paquete 01 (ginecología y obstetricia)"""
from lote01a import Q
import lote01a
L = []
lote01a.L = L
WIL = "Williams Obstetricia 26.ª ed. (2022)"
ACOG222 = "ACOG Practice Bulletin N.º 222, Hipertensión gestacional y preeclampsia (Obstet Gynecol 2020)"
GPC03 = "GPC 03-2025 INS/MINSA, Trastornos hipertensivos del embarazo"
ACOG228 = "ACOG Practice Bulletin N.º 228, Manejo de los leiomiomas uterinos sintomáticos (Obstet Gynecol 2021)"

Q(a="ginecologia", cat="Obstetricia", tema="Tratamiento de elección de la eclampsia", año=2014, ext=False,
  e="¿Cuál es el tratamiento de elección para eclampsia?",
  o=["Sulfato de magnesio.", "Fenobarbital.", "Alfametildopa.", "Nifedipino.", "Hidroclorotiazida."], k="A",
  c="La eclampsia es la aparición de convulsiones tonicoclónicas generalizadas en una gestante con preeclampsia, sin otra causa que las explique, y puede ocurrir antes, durante o hasta semanas después del parto. Su fisiopatología se vincula con la disfunción endotelial, la pérdida de la autorregulación cerebral y el edema vasogénico (síndrome de encefalopatía posterior reversible). El fármaco de elección para tratarla y para prevenirla en la preeclampsia con criterios de severidad es el sulfato de magnesio: el ensayo Collaborative Eclampsia Trial (1995) lo mostró superior a diazepam y fenitoína, y el estudio MAGPIE (2002) redujo cerca de 58 % el riesgo de eclampsia. Se administra una dosis de carga de 4 a 6 g por vía intravenosa en 15 a 20 minutos y luego 1 a 2 g por hora, con vigilancia de reflejo patelar, frecuencia respiratoria mayor de 12 por minuto y diuresis superior a 30 mL por hora; el antídoto es el gluconato de calcio. El fenobarbital ya no se emplea como anticonvulsivante de primera línea. Alfametildopa y nifedipino controlan la presión arterial pero no previenen ni detienen las convulsiones, y la hidroclorotiazida no tiene lugar en este cuadro. Perla clínica: tras la crisis se estabiliza a la madre y se programa la finalización del embarazo, y la recurrencia obliga a un nuevo bolo de magnesio y a descartar otras causas neurológicas.",
  f="Altman y cols., MAGPIE Trial (Lancet 2002); " + ACOG222 + "; " + GPC03 + "; " + WIL)

Q(a="ginecologia", cat="Obstetricia", tema="Hallazgos fisiopatológicos de la preeclampsia severa", año=2014, ext=True,
  e="Las pacientes con preeclampsia severa tienen disminución:",
  o=["Del ácido úrico.", "Del sodio corporal total.", "De las pruebas séricas hepáticas.", "De las aminas presoras.", "Del volumen plasmático."], k="E",
  c="La preeclampsia es un trastorno multisistémico que nace de una placentación anormal: las arterias espirales no se remodelan, hay isquemia placentaria y liberación de factores antiangiogénicos (sFlt-1, endoglina soluble) que dañan el endotelio materno. La consecuencia es vasoconstricción generalizada, aumento de la permeabilidad capilar y salida de líquido al espacio extravascular, por lo que el volumen plasmático se reduce hasta cerca de 9 a 12 % respecto de lo esperado, con hemoconcentración y riesgo de hipoperfusión de órganos. Esa contracción del volumen es lo que disminuye, y por eso la respuesta es E. El ácido úrico sube, tanto por mayor producción como por menor excreción renal; el sodio corporal total aumenta por la mayor reabsorción tubular, lo que explica el edema; las enzimas hepáticas (TGO, TGP, LDH) se elevan en las formas graves y forman parte de los criterios de severidad; y la sensibilidad a las aminas presoras como la angiotensina II está aumentada, no disminuida, lo que explica la hipertensión. Perla clínica: por la contracción del volumen intravascular, el edema pulmonar es un riesgo real, de modo que la hidratación en estas pacientes debe ser restrictiva y vigilada, a diferencia del shock hipovolémico clásico.",
  f=ACOG222 + "; " + GPC03 + "; " + WIL)

Q(a="ginecologia", cat="Obstetricia", tema="Preeclampsia con criterios de severidad con compromiso renal y plaquetario", año=2014, ext=False,
  e="Mujer de 32 años con 38 semanas de gestación, con cefalea y trastornos visuales, sin contracciones uterinas. G6 P5005. Examen: PA 152/112 mmHg en dos controles con 6 horas de intervalo. Proteinuria 2+, oliguria, creatinina sérica elevada, trombocitopenia. FCF 136 por minuto, feto vivo, no en trabajo de parto. ¿Cuál es el diagnóstico más probable?",
  o=["Preeclampsia severa.", "Hipertensión gestacional.", "Hipertensión crónica.", "Eclampsia.", "Preeclampsia sobreimpuesta."], k="A",
  c="La preeclampsia se define por presión arterial de 140/90 mmHg o más en dos tomas separadas por 4 horas, después de las 20 semanas, con proteinuria o con disfunción de órgano blanco. Se considera con criterios de severidad cuando existe cualquiera de estos hallazgos: presión sistólica de 160 o diastólica de 110 mmHg o más, plaquetas menores de 100 000/mm³, transaminasas el doble del límite normal, creatinina mayor de 1,1 mg/dL o el doble del basal, edema pulmonar, o cefalea y alteraciones visuales de aparición reciente. La paciente tiene una diastólica de 112 mmHg, trombocitopenia, oliguria con creatinina alta y síntomas neurológicos, es decir, varios criterios simultáneos, lo que define la preeclampsia severa. La hipertensión gestacional no tiene proteinuria ni daño de órgano; la hipertensión crónica precede a las 20 semanas y no explica la trombocitopenia ni la insuficiencia renal aguda; la eclampsia exige convulsiones, que aquí no hay; y la sobreimpuesta requiere antecedente de hipertensión crónica, que el enunciado no menciona. El manejo es hospitalario, con sulfato de magnesio, antihipertensivos de acción rápida (labetalol o nifedipino) y finalización del embarazo, que a las 38 semanas no se retrasa. Perla clínica: ante trombocitopenia y transaminasas elevadas, se debe vigilar la evolución a síndrome HELLP.",
  f=ACOG222 + "; " + GPC03 + "; " + WIL)

Q(a="ginecologia", cat="Obstetricia", tema="Dosis de ácido fólico con antecedente de defecto del tubo neural", año=2015, ext=False,
  e="Gestante de 20 años acude a su control prenatal con una gestación de 5 semanas por FUR confiable. Refiere antecedente de un hijo con defecto del tubo neural. ¿Cuál es la dosis de ácido fólico, en mg, recomendada como componente nutricional?",
  o=["4.", "12.", "8.", "6.", "10."], k="A",
  c="Los defectos del tubo neural (anencefalia, espina bífida, encefalocele) resultan de la falla del cierre del tubo entre los días 21 y 28 posconcepción, un momento en que muchas mujeres aún ignoran su embarazo. El folato es cofactor de la síntesis de purinas y timidilato y de la metilación del ADN, y su carencia compromete la proliferación del neuroepitelio. El estudio del Medical Research Council (1991) demostró que 4 mg diarios reducían cerca de 72 % la recurrencia en mujeres con un hijo afectado, y desde entonces la recomendación para esta situación es de 4 mg al día, idealmente desde un mes antes de la concepción y durante el primer trimestre. La población general en edad fértil requiere solo 0,4 a 0,8 mg diarios. Las dosis de 6, 8, 10 o 12 mg no ofrecen mayor protección demostrada y exponen innecesariamente a la paciente a enmascarar una deficiencia de vitamina B12. La misma dosis alta se indica con valproato, carbamazepina, diabetes pregestacional, obesidad o malabsorción. Aunque la paciente ya cursa 5 semanas, el tubo neural está por cerrar o acaba de hacerlo, por lo que se inicia la dosis de inmediato. Perla clínica: una ecografía morfológica y la alfafetoproteína ayudan a vigilar el defecto aun con la prevención adecuada.",
  f="USPSTF, Suplementación con ácido fólico para prevenir defectos del tubo neural (JAMA 2023); MRC Vitamin Study Research Group (Lancet 1991); " + WIL)

Q(a="ginecologia", cat="Ginecología", tema="Enfermedad pélvica inflamatoria: estadio con pelviperitonitis", año=2015, ext=False,
  e="Mujer de 25 años acude por dolor intenso hipogástrico y fiebre de 4 días. Examen clínico: T 38 °C, dolor a la descompresión en hemiabdomen, dolor uterino y a la movilización cervical, sin masas anexiales. ¿Cuál es el grado de enfermedad pélvica inflamatoria?",
  o=["IIIb.", "I.", "II.", "IIIa.", "IV."], k="C",
  c="La enfermedad pélvica inflamatoria (EPI) es la infección ascendente del tracto genital superior, causada por Chlamydia trachomatis, Neisseria gonorrhoeae y flora polimicrobiana. Los criterios mínimos de los CDC (2021) para iniciar tratamiento empírico son dolor pélvico o abdominal bajo con dolor a la movilización cervical, dolor uterino o dolor anexial. La clasificación clásica en estadios distingue el I, salpingitis aguda sin pelviperitonitis; el II, salpingitis con pelviperitonitis; el III, salpingitis con formación de absceso tuboovárico (con subtipos según el compromiso de uno o ambos anexos); y el IV, rotura del absceso. La paciente presenta signos de irritación peritoneal pélvica (dolor a la descompresión) sin masas anexiales, lo que corresponde al estadio II. El estadio I carece de signos peritoneales; el IIIa y el IIIb exigen una tumoración anexial o un absceso que aquí no se palpa; y el IV implica abdomen agudo con shock séptico. El manejo de la forma con peritonismo suele ser hospitalario, con ceftriaxona, doxiciclina y metronidazol por vía parenteral, y se pasa a vía oral al mejorar. Perla clínica: el tratamiento temprano evita infertilidad tubárica, embarazo ectópico y dolor pélvico crónico, y se debe tratar a la pareja.",
  f="Workowski y cols., CDC Sexually Transmitted Infections Treatment Guidelines 2021 (MMWR Recomm Rep 2021); " + WIL,
  nota="La clasificación en estadios I-IV citada por el libro es de uso didáctico; la guía CDC 2021 no la emplea y clasifica por gravedad clínica. Clave C (estadio II) del libro se mantiene.")

Q(a="ginecologia", cat="Obstetricia", tema="Altura uterina y edad gestacional (regla de McDonald)", año=2015, ext=False,
  e="En el embarazo normal, la altura del fondo uterino en centímetros guarda una relación cercana con la edad gestacional entre las semanas:",
  o=["13-19.", "35-36.", "37-38.", "20-34.", "39-42."], k="D",
  c="La altura uterina se mide con cinta métrica desde el borde superior de la sínfisis del pubis hasta el fondo del útero, con la gestante en decúbito dorsal y la vejiga vacía. La regla de McDonald establece que, entre las semanas 20 y 34 de gestación, la altura en centímetros equivale aproximadamente a las semanas cumplidas, con una variación de más o menos 2 cm; por ejemplo, a las 28 semanas el fondo se halla cerca de 28 cm. Antes de las 20 semanas el útero es todavía un órgano pélvico o apenas abdominal y la medida no es confiable, y de ahí que el rango 13-19 no sea correcto. Después de la semana 34, el crecimiento del feto se enlentece, la cabeza se encaja, y el volumen de líquido amniótico y la posición fetal hacen que la relación se pierda, por lo cual las semanas 35-36, 37-38 y 39-42 no mantienen la correlación. Una altura uterina menor a la esperada sugiere restricción del crecimiento, oligohidramnios o error de fechas, y una mayor orienta a macrosomía, polihidramnios, embarazo múltiple o mola. Se confirma con ecografía. Perla clínica: la altura uterina es un tamizaje simple y barato en el primer nivel, pero el diagnóstico de restricción del crecimiento fetal siempre se apoya en la biometría ecográfica.",
  f=WIL + "; Moore, Embriología clínica 11.ª ed. (2020)",
  nota="El libro explica el rango como 20-31 semanas en el comentario, pero marca 20-34 como respuesta; se mantiene D.")

Q(a="ginecologia", cat="Ginecología", tema="Estadificación POP-Q del prolapso de pared anterior", año=2015, ext=True,
  e="Mujer de 65 años con sensación de bulto en la vagina. Al examen, la pared anterior de la vagina protruye por fuera del introito; según la clasificación de prolapso de órganos pélvicos (POP-Q), el punto Ba está en +3 y la longitud total de la vagina es de 6 cm. ¿Cuál es el estadio de la distopia genital del punto Ba?",
  o=["II.", "III.", "I.", "IV.", "V."], k="B",
  c="El prolapso de órganos pélvicos es el descenso de las paredes vaginales y de los órganos vecinos por debilidad del soporte del piso pélvico; la pared anterior implica cistocele y es la más frecuente. La clasificación POP-Q (Bump, 1996) mide seis puntos respecto del himen, que es el nivel 0: Aa y Ba en la pared anterior, Ap y Bp en la posterior, C en el cuello y D en el fondo de saco. Los estadios se asignan por el punto más distal: el 0 no tiene prolapso; el I, cuando el punto más descendido está a más de 1 cm por encima del himen (menor de -1); el II, entre -1 y +1 cm; el III, desde más de +1 cm y hasta la longitud vaginal total menos 2 cm; y el IV, cuando se extiende más allá de ese valor, que corresponde a la eversión casi completa. Aquí Ba +3 supera +1 y no pasa de 6 - 2 = +4, por lo que se trata del estadio III; no existe el estadio V. El manejo incluye pesario, ejercicios del piso pélvico y estrógenos locales, y cirugía (colporrafia anterior o fijación a ligamento sacroespinoso) si hay síntomas importantes. Perla clínica: antes de reparar un prolapso se debe descartar incontinencia urinaria oculta.",
  f="Bump y cols., Estandarización de la terminología del prolapso de órganos pélvicos (Am J Obstet Gynecol 1996); ACOG Practice Bulletin N.º 214, Prolapso de órganos pélvicos (Obstet Gynecol 2019); " + WIL)

Q(a="ginecologia", cat="Obstetricia", tema="Preeclampsia con signos neurológicos y presión no severa", año=2015, ext=False,
  e="Gestante de 35 semanas, con control prenatal a las 12 semanas con PA 110/70 mmHg. Acude por cefalea tipo latido, visión borrosa y PA 140/90 mmHg que se confirma 6 horas después; proteinuria de 300 mg en muestra al azar y plaquetas 200 000/mm³. ¿Cuál es el diagnóstico más probable?",
  o=["Preeclampsia severa.", "Hipertensión crónica.", "Síndrome de HELLP.", "Preeclampsia leve.", "Hipertensión gestacional."], k="A",
  c="Una gestante normotensa que desarrolla presión de 140/90 mmHg o más después de las 20 semanas, confirmada con intervalo de al menos 4 horas, y que además muestra proteinuria o daño de órgano, tiene preeclampsia. El punto decisivo es la presencia de criterios de severidad, ya que basta uno solo: presión de 160/110 mmHg o más, plaquetas menores de 100 000/mm³, transaminasas el doble del normal, creatinina mayor de 1,1 mg/dL, edema pulmonar, o cefalea y alteraciones visuales de reciente inicio. La cefalea pulsátil con visión borrosa expresa irritación cortical y obliga a clasificar el cuadro como preeclampsia con criterios de severidad, aunque la presión arterial y las plaquetas estén en rango no severo. La hipertensión gestacional carece de proteinuria y de síntomas neurológicos; la hipertensión crónica debió estar presente antes de la semana 20, y la paciente tenía 110/70 a las 12 semanas; el HELLP requiere hemólisis, enzimas elevadas y plaquetas bajas, que aquí faltan. La actual guía ACOG ya no usa el término preeclampsia leve, pues toda preeclampsia puede progresar. El manejo es hospitalario, con sulfato de magnesio, control de la presión y finalización del embarazo a partir de las 34 semanas, por tanto, sin postergarla. Perla clínica: los síntomas neurológicos deben tratarse como inminencia de eclampsia.",
  f=ACOG222 + "; " + GPC03 + "; " + WIL,
  nota="La opción D usa el término «leve», que ACOG 2020 ya no recomienda; la clave A se mantiene.")

Q(a="ginecologia", cat="Obstetricia", tema="Causa más frecuente de hemorragia posparto", año=2015, ext=True,
  e="¿Cuál es la causa más frecuente de hemorragia posparto?",
  o=["Rotura uterina.", "Desgarro vaginal.", "Laceración cervical.", "Inversión uterina.", "Atonía uterina."], k="E",
  c="Se define hemorragia posparto como la pérdida acumulada de 1000 mL o más, o cualquier sangrado con signos de hipovolemia en las primeras 24 horas, y es la primera causa de muerte materna en el mundo. Para el abordaje se usa la nemotecnia de las cuatro T: tono, trauma, tejido y trombina. La atonía uterina corresponde al tono y explica casi 70 % de los casos: tras el alumbramiento, las ligaduras vivientes de Pinard (la contracción del miometrio que cierra los vasos del lecho placentario) fallan, y el útero llega a perder un litro de sangre en pocos minutos. Predisponen la sobredistensión (macrosomía, gemelar, polihidramnios), el trabajo de parto prolongado, la multiparidad, la corioamnionitis y los uterolíticos. El trauma del canal (desgarros vaginales o cervicales, rotura e inversión uterina) explica cerca de 20 %, por lo cual las demás opciones son menos frecuentes. El manejo escalonado comienza con masaje uterino y oxitocina, y sigue con ácido tranexámico, ergometrina, carboprost o misoprostol, taponamiento con balón, suturas compresivas y, como último recurso, histerectomía. Perla clínica: el manejo activo del tercer período del parto, con oxitocina inmediata, es la medida preventiva más eficaz y se aplica a todas las parturientas.",
  f="ACOG Practice Bulletin N.º 183, Hemorragia posparto (Obstet Gynecol 2017); " + WIL,
  nota="REPITE indicado como RM-GAS-021, pero ese ID corresponde a otra pregunta (hemorragia digestiva alta, clave B). Es falsa coincidencia; aquí la clave es E (atonía uterina), la del libro. Comentario con otro ángulo que el de la pregunta de puerperio inmediato del lote 6.")

Q(a="ginecologia", cat="Obstetricia", tema="Placenta previa con cesáreas previas: acretismo placentario", año=2015, ext=True,
  e="Gestante de 32 semanas con antecedente de tres cesáreas previas. Ecografía: placenta previa total. ¿Cuál sería el mayor riesgo al que se enfrenta esta paciente?",
  o=["Desprendimiento prematuro de placenta.", "Vasa previa.", "Rotura uterina.", "Rotura prematura de membranas.", "Acretismo placentario."], k="E",
  c="El espectro del acretismo placentario (acreta, increta y percreta) consiste en la invasión anormal del miometrio por las vellosidades, por defecto de la decidua basal sobre una cicatriz uterina. Su factor de riesgo principal es la cirugía uterina previa, sobre todo la cesárea, y el riesgo crece con el número de cicatrices y se multiplica cuando la placenta es previa y está sobre ellas: con placenta previa, es de 3 % con una cesárea previa, cerca de 11 % con dos, 40 % con tres y por encima de 60 % con cuatro o más. Por eso en esta paciente es el mayor peligro, y su consecuencia es hemorragia masiva en el parto, histerectomía obstétrica, transfusión masiva, lesión de vejiga o ureteros y mortalidad materna. La sospecha se confirma con ecografía Doppler y resonancia magnética en casos dudosos. La rotura uterina es un riesgo más ligado al trabajo de parto con cicatriz, el desprendimiento se asocia a hipertensión y tabaco, la vasa previa a inserción velamentosa y la rotura de membranas a infección, ninguno de ellos tan determinante aquí. El manejo es cesárea programada, entre las 34 y 36 semanas, con equipo multidisciplinario y en un centro con banco de sangre. Perla clínica: ante placenta previa con cicatrices uterinas, se busca activamente el acretismo.",
  f="ACOG y SMFM, Obstetric Care Consensus N.º 7, Espectro de placenta acreta (Obstet Gynecol 2018); " + WIL,
  nota="Las cifras de riesgo por número de cesáreas varían entre estudios (Silver 2006); se citan de forma aproximada.")

Q(a="ginecologia", cat="Ginecología", tema="Mioma submucoso y alteración menstrual característica", año=2015, ext=True,
  e="Mujer de 36 años, abortadora recurrente, acude para consejería preconcepcional. Dice tener una ecografía compatible con leiomioma uterino. Si el leiomioma submucoso fuera el causante de las pérdidas recurrentes, ¿cuál sería la alteración menstrual característica?",
  o=["Oligomenorrea.", "Hipermenorrea.", "Menstruación normal.", "Polimenorrea.", "Amenorrea."], k="B",
  c="Los leiomiomas son tumores benignos monoclonales del músculo liso uterino, dependientes de estrógenos y progesterona, y la clasificación FIGO los ubica como submucosos (tipos 0 a 2), intramurales o subserosos. Aunque los submucosos son solo 5 a 10 % del total, son los que más síntomas causan: deforman la cavidad endometrial, ensanchan la superficie sangrante, alteran la contractilidad y la vascularización del endometrio y producen hipermenorrea o menorragia, es decir, sangrado menstrual abundante o prolongado de ciclo regular, además de anemia por deficiencia de hierro. También interfieren con la implantación y favorecen la pérdida gestacional, razón por la cual son relevantes en la paciente con abortos recurrentes. La oligomenorrea y la amenorrea sugieren anovulación o causas endocrinas; la polimenorrea, ciclos muy cortos por disfunción lútea; y un ciclo normal es poco compatible con un mioma submucoso sintomático. Este tipo de mioma es una de las causas de sangrado uterino anormal del grupo estructural PALM (L de leiomioma). El diagnóstico se apoya en la ecografía transvaginal, la histerosonografía y la histeroscopia. Perla clínica: la hipermenorrea con anemia en una mujer con ciclos regulares debe hacer pensar en mioma submucoso o en pólipo antes que en una causa hormonal.",
  f=ACOG228 + "; Munro y cols., Clasificación FIGO de las causas de sangrado uterino anormal (Semin Reprod Med 2011); " + WIL,
  nota="En el libro las opciones B y E aparecían ambas como «Hipermenorreas» por OCR/duplicado; se reemplazó la E por «Amenorrea» como distractor plausible. Clave B del libro.")

Q(a="ginecologia", cat="Ginecología", tema="Localización del mioma que produce hipermenorrea", año=2015, ext=True,
  e="Mujer de 36 años acude por sangrado abundante durante la menstruación. Refiere tener una ecografía con diagnóstico de miomatosis uterina múltiple. ¿Cuál sería la localización, según la patología de la paciente?",
  o=["Subseroso.", "Submucoso.", "Intramural.", "Intraligamentario.", "Cervical."], k="B",
  c="La miomatosis uterina es la neoplasia benigna más frecuente de la mujer y se presenta en hasta 70 % de las mujeres antes de la menopausia, aunque solo una parte tiene síntomas. El tipo de síntoma depende de la localización. Los submucosos, que protruyen hacia la cavidad endometrial, producen el sangrado menstrual abundante, por mayor superficie endometrial, ulceración y alteración de la hemostasia local; pueden causar anemia severa e infertilidad. Los intramurales aumentan el tamaño uterino y pueden causar sangrado, aunque con menor frecuencia, y sobre todo sensación de pesadez. Los subserosos crecen hacia la superficie peritoneal y producen síntomas por compresión de vejiga, recto o nervios (polaquiuria, estreñimiento, dolor), con poca alteración de la menstruación. Los intraligamentarios y los cervicales son raros y se manifiestan por compresión ureteral u obstrucción del canal. Por tanto, la queja principal de sangrado excesivo apunta a la localización submucosa. El diagnóstico se hace con ecografía transvaginal y, si hay duda, con resonancia magnética o histeroscopia. El tratamiento médico incluye antifibrinolíticos, anticonceptivos, DIU de levonorgestrel y antagonistas de la GnRH con terapia add-back, y el quirúrgico depende del deseo reproductivo. Perla clínica: la paciente con sangrado abundante necesita hemoglobina y ferritina antes de decidir el tratamiento.",
  f=ACOG228 + "; Munro y cols., Clasificación FIGO de las causas de sangrado uterino anormal (Semin Reprod Med 2011); " + WIL)

Q(a="ginecologia", cat="Ginecología", tema="Tratamiento del mioma submucoso sintomático", año=2015, ext=True,
  e="Mujer de 36 años acude por presentar hipermenorreas y anemia. Tiene ecografía compatible con leiomioma uterino submucoso. ¿Cuál es el tratamiento más apropiado?",
  o=["Histeroscopia quirúrgica.", "Miomectomía convencional.", "Histerectomía total.", "Histerectomía subtotal.", "Legrado uterino."], k="A",
  c="El leiomioma submucoso es el que más frecuentemente causa hipermenorrea, anemia e infertilidad o pérdida gestacional, y los tipos 0 y 1 de FIGO, completamente o en más de la mitad intracavitarios, y de hasta 4 a 5 cm de diámetro, se resecan por histeroscopia operatoria (resectoscopia). Esta vía es mínimamente invasiva, no requiere abrir el abdomen ni cortar la pared uterina, tiene recuperación rápida, preserva el útero y la fertilidad, y evita el riesgo de rotura uterina en embarazos futuros. La miomectomía abdominal o laparoscópica se reserva para los miomas intramurales o subserosos o los submucosos tipo 2 muy grandes. La histerectomía, total o subtotal, es definitiva y se ofrece si la paciente ya no desea más hijos y fracasaron otras medidas, lo que no se plantea en una mujer de 36 años sin esa información. El legrado uterino no extirpa el mioma, apenas controla momentáneamente el sangrado, y tiene riesgo de perforación. Antes de operar se puede mejorar la anemia con hierro y, si es necesario, pretratar con antagonista de GnRH. Perla clínica: ante una paciente con hipermenorrea y anemia en edad fértil, se debe conservar el útero siempre que sea posible y la histeroscopia es la primera opción para los submucosos.",
  f=ACOG228 + "; Munro y cols., Clasificación FIGO de las causas de sangrado uterino anormal (Semin Reprod Med 2011); " + WIL,
  nota="El bloque trae pegado texto de otra pregunta del libro; se usó solo el enunciado del mioma submucoso. Clave A.")

Q(a="infectologia", cat="Dengue en gestantes", tema="Gestante con síndrome febril tras viaje a zona de dengue", año=2015, ext=True,
  e="Gestante de 19 años acude a consulta externa por fiebre continua de 39 °C que comenzó ese mismo día. Refiere mialgia intensa en todo el cuerpo y dolor retroorbitario. Hace 3 días estuvo en Tumbes visitando a un familiar. La fiebre cae luego de terapia antifebril, pero no llega a la normalidad. ¿Cuál es la indicación a seguir?",
  o=["Dar de alta con indicaciones de AINES.", "Dar de alta con indicaciones de paracetamol.", "Prescribir 3 litros de agua y citar al día siguiente para análisis.", "Dar de alta y solo prescribir medios físicos.", "Internamiento con vigilancia continua."], k="E",
  c="La fiebre de inicio brusco con mialgias y dolor retroorbitario en una persona que visitó una zona endémica (Tumbes) corresponde a un caso probable de dengue, enfermedad viral transmitida por Aedes aegypti. Su evolución tiene tres fases: febril, crítica (entre los días 3 y 7, cuando cae la fiebre y pueden aparecer fuga plasmática, hemoconcentración, plaquetopenia y choque) y de recuperación. La gestación es una condición de riesgo que clasifica a la paciente en el grupo B de la OMS (con comorbilidad o riesgo social), no en el A de manejo ambulatorio, por lo que requiere hospitalización u observación estrecha, con hemograma seriado, hematocrito y plaquetas, vigilancia de signos de alarma (dolor abdominal, vómitos persistentes, sangrado, letargia) y control de la salud fetal. El dengue en el embarazo aumenta el riesgo de parto prematuro, hemorragia y transmisión vertical. Los AINES y la aspirina están contraindicados por el riesgo hemorrágico; solo se admite paracetamol. Un alta con paracetamol o medios físicos expondría a la paciente a la fase crítica sin supervisión, y la hidratación oral sin vigilancia es insuficiente. Perla clínica: la caída de la fiebre no indica mejoría sino el inicio de la fase crítica, y las plaquetas bajas y el hematocrito en ascenso son las alertas.",
  f="OMS, Dengue: guías para el diagnóstico, tratamiento, prevención y control (2009); MINSA, NTS N.º 211-MINSA/DGIESP-2024, Atención integral del paciente con dengue (RM 175-2024/MINSA); " + WIL,
  nota="El bloque trae pegado texto de otra pregunta (factor de riesgo para transferencia, n.º 8); se usó solo la pregunta de la gestante febril, clave E. La NTS 211-2024 tuvo una modificación parcial en 2025 (RM 473-2025/MINSA, deroga el anexo 04); se cita sin detallar anexos.")

Q(a="ginecologia", cat="Obstetricia", tema="Malformaciones por rubéola congénita en el primer trimestre", año=2015, ext=True,
  e="Mujer con cinco semanas de gestación se infecta con el virus de la rubéola. ¿Cuáles son las malformaciones congénitas más probables?",
  o=["Hipoplasia nasal o retraso mental.", "Defectos de reducción en los miembros.", "Cataratas o cardiopatías congénitas.", "Hipertrofia de clítoris y fusión de labios.", "Hipertrofia de miembros superiores e inferiores."], k="C",
  c="El virus de la rubéola es un togavirus que atraviesa la placenta durante la viremia materna y produce el síndrome de rubéola congénita. El riesgo de infección fetal y de defectos es máximo en las primeras 8 a 12 semanas, y puede llegar a 80 a 90 % antes de las 12 semanas, con aborto espontáneo frecuente, y disminuye luego, para volverse bajo después de las 20 semanas. La organogénesis explica el patrón: en el primer trimestre se afectan el ojo (catarata, glaucoma, retinopatía en sal y pimienta), el corazón (persistencia del conducto arterioso, estenosis de la arteria pulmonar), el oído interno (sordera neurosensorial, la secuela más frecuente) y el sistema nervioso (microcefalia, retraso mental). Por eso la tríada clásica de Gregg es catarata, cardiopatía y sordera. Las demás opciones no corresponden: los defectos de reducción de miembros se asocian a talidomida; la virilización genital, a andrógenos o a la hiperplasia suprarrenal; la hipoplasia nasal, a warfarina o a fenitoína; y la hipertrofia de miembros no es un hallazgo de la rubéola. No existe tratamiento antiviral específico, y la prevención es la vacuna triple viral antes del embarazo, que está contraindicada durante él. Perla clínica: una gestante susceptible se vacuna en el posparto inmediato y se evita el embarazo por un mes tras la vacuna.",
  f=WIL + "; Nelson Tratado de Pediatría 22.ª ed. (2024)")

Q(a="ginecologia", cat="Obstetricia", tema="Deflexión de tercer grado: presentación de cara", año=2016, ext=False,
  e="En una deflexión de III grado, ¿cuáles son las estructuras anatómicas palpables al tacto vaginal?",
  o=["Arcos supraorbitarios y mentón.", "Sutura frontal y lambdoidea.", "Dorso de la nariz y sutura bregmática.", "Fontanela anterior y borde orbitario.", "Dorso de la nariz y fontanela lambdoidea."], k="A",
  c="La actitud normal del feto en el trabajo de parto es la flexión de la cabeza, que presenta al canal el diámetro suboccipitobregmático (9,5 cm) más pequeño. La deflexión es la extensión parcial o total de la cabeza y se clasifica en tres grados según el punto guía que se presenta. La de primer grado es la presentación de bregma o sincipucio, en la que se palpa la fontanela anterior y la sutura sagital y metópica. La de segundo grado es la presentación de frente, con dorso de la nariz y bordes orbitarios como estructuras palpables, y es la más distócica, porque presenta el diámetro occipitomentoniano de 13,5 cm y no suele resolverse por vía vaginal. La de tercer grado es la presentación de cara, con extensión máxima, y se palpan el mentón, la boca, la nariz y los arcos supraorbitarios; el mentón es el punto de referencia. Las combinaciones que mencionan la fontanela lambdoidea o la sutura frontal con la lambdoidea no se corresponden con ninguna deflexión, porque la lambdoidea queda en el occipucio. En la presentación de cara con el mentón anterior es posible el parto vaginal, mientras que con mentón posterior se indica cesárea. Perla clínica: no se debe confundir la boca con el ano en la presentación podálica ni la cara con la nalga.",
  f=WIL,
  nota="El OCR dejó la clave vacía; la imagen del libro marca «Respuesta A». La perla final del comentario se mantiene sobre diagnóstico diferencial en el tacto.")

Q(a="ginecologia", cat="Obstetricia", tema="Degeneración más frecuente del mioma en el embarazo", año=2016, ext=False,
  e="En una gestante con diagnóstico de miomatosis uterina, ¿cuál es el tipo más frecuente de degeneración que presentan los miomas?",
  o=["Roja.", "Cálcica.", "Grasa.", "Sarcomatosa.", "Quística."], k="A",
  c="Los leiomiomas aparecen en 1 a 6 % de las gestaciones, y la mayoría no produce complicaciones, porque el estímulo estrogénico y el aumento del flujo uterino los hacen crecer en el primer trimestre pero luego se estabilizan. Cuando su crecimiento supera al aporte vascular, sobre todo en los miomas grandes, de más de 5 cm, ocurre infarto hemorrágico con necrosis aséptica del tumor, y el cuadro se conoce como degeneración roja o carnosa, porque el tejido toma un color rojo oscuro por la hemólisis. Es la complicación más característica del embarazo, típica del segundo trimestre y del puerperio, y se presenta con dolor abdominal localizado, fiebre baja, leucocitosis leve y náuseas. La degeneración cálcica ocurre en mujeres posmenopáusicas, la grasa y la quística son infrecuentes, y la transformación sarcomatosa es excepcional, de menos de 1 % de los casos. El diagnóstico se hace por ecografía y el tratamiento es conservador: reposo, analgesia con paracetamol, hidratación y, de ser necesario, AINES por cortos periodos antes de las 32 semanas; la miomectomía durante la gestación se evita. Perla clínica: el dolor del mioma en degeneración roja puede confundirse con apendicitis, pielonefritis o desprendimiento de placenta, por lo cual el diagnóstico es de exclusión.",
  f=ACOG228 + "; " + WIL)
